import { styles } from './color-helper.styles';
import { camelToKebabCase, kebabToCamelCase } from './string-helper';
export class ColorHelper {
    static { this.brandColors = ColorHelper.mapToKirbyColorArray(styles.brandColors); }
    static { this.notificationColors = ColorHelper.mapToKirbyColorArray(styles.notificationColors); }
    static { this.decorationColors = ColorHelper.mapToKirbyColorRampArray(styles.decorationColors); }
    static { this.systemColors = ColorHelper.mapToKirbyColorArray(styles.systemColors); }
    static { this.textColors = ColorHelper.mapToKirbyColorArray(styles.textColors, styles.kirbyTextColors); }
    static { this.mainColors = ColorHelper.getMainColors(); }
    static getMainColors() {
        // Do not remove the `colorArray` const, since it'll break the ngpackagr build, for more info see:
        // https://github.com/ng-packagr/ng-packagr/issues/696
        const colorArray = Object.entries(styles.mainColors).map(([name, value]) => ({ name, value }));
        return colorArray;
    }
    static mapToKirbyColorArray(colors, fullColorMap = styles.kirbyColors) {
        const TINT = 'Tint';
        const SHADE = 'Shade';
        const CONTRAST = 'Contrast';
        const colorArray = Object.entries(colors).map(([name, value]) => ({
            name: camelToKebabCase(name),
            value,
            base: value,
            tint: {
                value: fullColorMap[name + TINT],
                name: camelToKebabCase(name + TINT),
            },
            shade: {
                value: fullColorMap[name + SHADE],
                name: camelToKebabCase(name + SHADE),
            },
            contrast: {
                value: fullColorMap[name + CONTRAST],
                name: camelToKebabCase(name + CONTRAST),
            },
        }));
        // Do not remove the `colorArray` const, since it'll break the ngpackagr build, for more info see:
        // https://github.com/ng-packagr/ng-packagr/issues/696
        return colorArray;
    }
    static mapToKirbyColorRampArray(colors) {
        const colorArray = Object.entries(colors).map(([name, value]) => ({
            name: camelToKebabCase(name),
            ramp: Object.entries(value).map(([step, rampValue]) => ({
                step,
                value: rampValue,
            })),
        }));
        // Do not remove the `colorArray` const, since it'll break the ngpackagr build, for more info see:
        // https://github.com/ng-packagr/ng-packagr/issues/696
        return colorArray;
    }
    static getBackgroundColor() {
        return ColorHelper.getColor('background-color');
    }
    static getColorBrightness(name) {
        return ColorHelper.getColor(name + '-color-brightness');
    }
    static getThemeColorRgbString(name, opacity) {
        const rgbValue = ColorHelper.getColor(name + '-rgb');
        return opacity
            ? `rgba(${rgbValue}, ${ColorHelper.opacityThreshold(opacity)})`
            : `rgb(${rgbValue})`;
    }
    static getThemeDecorationColorRgbString(name, step, opacity) {
        const rgb = ColorHelper.hexToRGB(ColorHelper.getDecorationColor(name, step));
        return opacity
            ? rgb.replace('rgb', 'rgba').replace(')', `, ${ColorHelper.opacityThreshold(opacity)})`)
            : rgb;
    }
    static getThemeTextColorRgbString(name) {
        const rgbValue = ColorHelper.getTextColor(name + '-rgb');
        return `rgb(${rgbValue})`;
    }
    static getThemeColorHexString(name) {
        return ColorHelper.getColor(name);
    }
    static getThemeDecorationColorHexString(name, step) {
        return ColorHelper.getDecorationColor(name, step);
    }
    static getThemeTextColorHexString(name) {
        return ColorHelper.getTextColor(name);
    }
    static getTransparentColorRgbString() {
        return 'rgba(0, 0, 0, 0)';
    }
    static colorStringToRgbString(color) {
        if (color.indexOf('rgb') === 0) {
            return color;
        }
        if (color.indexOf('#') === 0) {
            return ColorHelper.hexToRGB(color);
        }
        if (color.split(',').length === 3) {
            return `rgb(${color})`;
        }
        if (color.split(',').length === 4) {
            return `rgba(${color})`;
        }
        const ctx = document.createElement('canvas').getContext('2d');
        ctx.fillStyle = color;
        const renderedColor = ctx.fillStyle.toString();
        return ColorHelper.colorStringToRgbString(renderedColor);
    }
    static hexToRGB(hex) {
        let r = '0', g = '0', b = '0';
        // 3 digits
        if (hex.length === 4) {
            r = '0x' + hex[1] + hex[1];
            g = '0x' + hex[2] + hex[2];
            b = '0x' + hex[3] + hex[3];
            // 6 digits
        }
        else if (hex.length === 7) {
            r = '0x' + hex[1] + hex[2];
            g = '0x' + hex[3] + hex[4];
            b = '0x' + hex[5] + hex[6];
        }
        return `rgb(${+r}, ${+g}, ${+b})`;
    }
    static getColor(name) {
        const camelCaseKey = kebabToCamelCase(name);
        const found = styles.kirbyColors[camelCaseKey];
        const runTimeColor = window
            .getComputedStyle(document.documentElement)
            .getPropertyValue(`--kirby-${name}`);
        return runTimeColor || found || null;
    }
    static getDecorationColor(name, step) {
        const camelCaseKey = kebabToCamelCase(name);
        const found = styles.decorationColors[camelCaseKey][step];
        const runTimeColor = window
            .getComputedStyle(document.documentElement)
            .getPropertyValue(`--kirby-decoration-color-${name}-${step}`);
        return runTimeColor || found || null;
    }
    static getTextColor(name) {
        const camelCaseKey = kebabToCamelCase(name);
        const found = styles.kirbyTextColors[camelCaseKey];
        const runTimeColor = window
            .getComputedStyle(document.documentElement)
            .getPropertyValue(`--kirby-text-color-${name}`);
        return runTimeColor || found || null;
    }
    static opacityThreshold(opacity) {
        if (0 <= opacity && opacity <= 1) {
            return opacity;
        }
        console.warn(`Opacity value must be between 0 and 1. Current value is: ${opacity}.`);
        return 1;
    }
}
